#!/usr/bin/env node
let alphabet,size,{nanoid:nanoid,customAlphabet:customAlphabet}=require("..");function print(e){process.stdout.write(e+"\n")}function error(e){process.stderr.write(e+"\n"),process.exit(1)}(process.argv.includes("--help")||process.argv.includes("-h"))&&(print("\n  Usage\n    $ nanoid [options]\n\n  Options\n    -s, --size       Generated ID size\n    -a, --alphabet   Alphabet to use\n    -h, --help       Show this help\n\n  Examples\n    $ nanoid --s 15\n    S9sBF77U6sDB8Yg\n\n    $ nanoid --size 10 --alphabet abc\n    bcabababca"),process.exit());for(let e=2;e<process.argv.length;e++){let s=process.argv[e];"--size"===s||"-s"===s?(size=Number(process.argv[e+1]),e+=1,(Number.isNaN(size)||size<=0)&&error("Size must be positive integer")):"--alphabet"===s||"-a"===s?(alphabet=process.argv[e+1],e+=1):error("Unknown argument "+s)}print(alphabet?customAlphabet(alphabet,size)():nanoid(size));